      }
    },
    {
      "claim_id": "C3",
      "text": "The SEGMENT_15 segment's income before tax as a percentage of segment sales increased from 33.2% in 2024 to 36.9% in 2025, demonstrating improved profitability within this segment (Item 7, EP_0009_E01).",
      "evidence_ids": [
        "EP_0009_E01"
      ],
      "check_spec": null
    },
    {
      "claim_id": "C4",
      "text": "The company's worldwide income before tax margin improved from 18.8% in 2024 to 34.6% in 2025 (Item 7, EP_0009_E01).",
      "evidence_ids": [
        "EP_0009_E01"
      ],
      "check_spec": null
    },
    {
      "claim_id": "C5",
      "text": "The company experienced a significant positive impact from acquisitions and divestitures on worldwide sales growth, contributing 1.1% in 2025, primarily due to PRODUCT_41 and ENTITY_09 (Item 7, EP_0009_E02). Loss of patent exclusivity for SEGMENT_15 products is often followed by substantial sales reductions due to generic/biosimilar competition (EP_0009_E03).",
